<template><div class="info-page page-animate"><div class="wrap info-wrap"><section class="info-hero"><span class="eyebrow">Performance leaderboard</span><h1>Monthly Tipster Rankings</h1><p>See which approved BraTipsters tipsters delivered the strongest verified results during each month.</p></section><section class="ranking-toolbar"><label>Ranking month <input type="month" v-model="month" @change="load"/></label><span>{{monthLabel}}</span></section><div v-if="loading" class="ranking-empty">Loading monthly rankings…</div><div v-else-if="error" class="error">{{error}} <button class="ghost" @click="load">Try again</button></div><div v-else-if="rows.length" class="ranking-list"><article v-for="(r,i) in rows" :key="r.userId" class="ranking-row"><div class="ranking-place">#{{i+1}}</div><div class="ranking-avatar">{{r.username?.[0]?.toUpperCase()||'T'}}</div><div class="ranking-main"><RouterLink :to="`/tipsters/${encodeURIComponent(r.username)}`"><b>{{r.username}}</b></RouterLink><small>{{r.settled}} settled tips · {{r.wins}} wins · {{r.losses}} losses</small></div><div class="ranking-metric"><span>Win rate</span><b>{{r.winRate.toFixed(1)}}%</b></div><div class="ranking-metric"><span>Profit</span><b :class="r.profit>=0?'positive':'negative'">{{r.profit>=0?'+':''}}{{r.profit.toFixed(2)}}</b></div><div class="ranking-metric"><span>ROI</span><b>{{r.roi.toFixed(1)}}%</b></div></article></div><div v-else class="ranking-empty">No settled tipster predictions were recorded for this month.</div><p class="ranking-note">Rankings are based on settled predictions recorded by BraTipsters for the selected calendar month. Void predictions do not count toward profit or wins.</p></div></div></template>
<script setup lang="ts">import {computed,onMounted,ref} from 'vue';import {RouterLink} from 'vue-router';import {api} from '../services/api';const d=new Date();const month=ref(`${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}`),rows=ref<any[]>([]),loading=ref(false),error=ref('');const monthLabel=computed(()=>{const [y,m]=month.value.split('-');return new Date(Number(y),Number(m)-1,1).toLocaleDateString(undefined,{month:'long',year:'numeric'})});async function load(){loading.value=true;error.value='';try{rows.value=(await api.get(`/tipsters/rankings?month=${month.value}`)).data||[]}catch(e:any){error.value=e?.message||'Unable to load rankings.'}finally{loading.value=false}}onMounted(load);</script>
